import{_ as r,a0 as s,w as i,s as d,ao as l,I as p,x as e,a1 as a,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何使用netstat命令驗證DDOS入侵 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用netstat命令驗證DDOS入侵 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用netstat命令驗證DDOS入侵 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用netstat命令驗證DDOS入侵 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/How to verify DDOS attack with netstat command on Linux Terminal","title":"如何使用netstat命令驗證DDOS入侵","tag":"201406","desc":""},"relativePath":"201406/How to verify DDOS attack with netstat command on Linux Terminal.md","filePath":"[post].md"}'),D={name:"201406/How to verify DDOS attack with netstat command on Linux Terminal.md"};function m(c,t,u,T,f,S){const n=s("Link");return i(),d("div",null,[t[11]||(t[11]=l(`<h1 id="如何使用netstat命令驗證ddos入侵" tabindex="-1">如何使用netstat命令驗證DDOS入侵 <a class="header-anchor" href="#如何使用netstat命令驗證ddos入侵" aria-label="Permalink to “如何使用netstat命令驗證DDOS入侵”">​</a></h1><p>一般來説，服務器非常慢可能原因是多方面的，有可能是配置錯誤，腳本錯誤或者是一些奇詭的硬件。當然也有可能是有人對你的服務器進行 Dos (拒絕服務攻擊)或者 DDOS (分佈式拒絕服務攻擊)。</p><p>Dos攻擊或者DDos攻擊目的是使服務器或者網絡資源耗盡，使其他用户無法使用。一般來説，這種攻擊主要針對重要的網站或服務，比如銀行、信用卡支付網關甚至是根域名服務器。Dos攻擊主要通過強制目標主機重啓或大量消耗其主機資源，使得目標主機無法提供服務或者妨害主機和用户之間的通信的手段，使得主機無法提供正常的服務的。</p><p>在本文中你將知道如何在終端中使用netstat命令判斷服務器是否遭受Dos攻擊。</p><p>netstat命令的用户手冊描述其作用是用來顯示網絡連接、路由表、接口統計、偽連接和組播成員的。</p><h3 id="一些例子和解釋" tabindex="-1">一些例子和解釋 <a class="header-anchor" href="#一些例子和解釋" aria-label="Permalink to “一些例子和解釋”">​</a></h3><pre><code>netstat -na
</code></pre><p>該命令將顯示所有活動的網絡連接。</p><pre><code>netstat -an | grep :80 | sort
</code></pre><p>顯示所有80端口的網絡連接並排序。這裏的80端口是http端口，所以可以用來監控web服務。如果看到同一個IP有大量連接的話就可以判定單點流量攻擊了。</p><pre><code>netstat -n -p|grep SYN_REC | wc -l
</code></pre><p>這個命令可以查找出當前服務器有多少個活動的 SYNC_REC 連接。正常來説這個值很小，最好小於5。 當有Dos攻擊或者郵件炸彈的時候，這個值相當的高。儘管如此，這個值和系統有很大關係，有的服務器值就很高，也是正常現象。</p><pre><code>netstat -n -p | grep SYN_REC | sort -u
</code></pre><p>列出所有連接過的IP地址。</p><pre><code>netstat -n -p | grep SYN_REC | awk &#39;{print $5}&#39; | awk -F: &#39;{print $1}&#39;
</code></pre><p>列出所有發送SYN_REC連接節點的IP地址。</p><pre><code>netstat -ntu | awk &#39;{print $5}&#39; | cut -d: -f1 | sort | uniq -c | sort -n
</code></pre><p>使用netstat命令計算每個主機連接到本機的連接數。</p><pre><code>netstat -anp |grep &#39;tcp|udp&#39; | awk &#39;{print $5}&#39; | cut -d: -f1 | sort | uniq -c | sort -n
</code></pre><p>列出所有連接到本機的UDP或者TCP連接的IP數量。</p><pre><code>netstat -ntu | grep ESTAB | awk &#39;{print $5}&#39; | cut -d: -f1 | sort | uniq -c | sort -nr
</code></pre><p>檢查 ESTABLISHED 連接並且列出每個IP地址的連接數量。</p><pre><code>netstat -plan|grep :80|awk {&#39;print $5&#39;}|cut -d: -f 1|sort|uniq -c|sort -nk 1
</code></pre><p>列出所有連接到本機80端口的IP地址和其連接數。80端口一般是用來處理HTTP網頁請求。</p><h3 id="如何減少dos攻擊" tabindex="-1">如何減少DOS攻擊 <a class="header-anchor" href="#如何減少dos攻擊" aria-label="Permalink to “如何減少DOS攻擊”">​</a></h3><p>一旦你獲得攻擊服務器的IP地址你就可以使用以下命令拒絕此IP的所有連接。</p><pre><code>iptables -A INPUT 1 -s $IPADRESS -j DROP/REJECT
</code></pre><p>注意，你需要將 $IPADRESS 替換成需要拒絕連接的IP地址。</p><p>執行完以上命令後，使用以下命令結束所有的httpd連接以清理系統。</p><pre><code>killall -KILL httpd
</code></pre><p>然後執行以下命令重啓httpd服務。</p><pre><code>service httpd start           #RedHat 系統 

/etc/init/d/apache2 restart   #Debian 系統
</code></pre><hr>`,33)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),a(n,{href:"http://linuxaria.com/howto/how-to-verify-ddos-attack-with-netstat-command-on-linux-terminal"},{default:o(()=>[...t[0]||(t[0]=[e("http://linuxaria.com/howto/how-to-verify-ddos-attack-with-netstat-command-on-linux-terminal",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=e("譯者：",-1)),a(n,{href:"https://github.com/shipsw"},{default:o(()=>[...t[2]||(t[2]=[e("shipsw",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),a(n,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const C=r(D,[["render",m]]);export{x as __pageData,C as default};
